import { A4, FOOTER_LAYOUT, IMAGE_LIMIT, THEMES, TEMPLATES, sanitizeRichText, plainTextToRichText, inlineTextRuns, companyAddressLines, buildFooterLines, buildLetterPages, validateLetter } from "./core.js";
let savedEditorRange=null;
queueMicrotask(()=>{
  const editor=document.getElementById("message"),inside=range=>range&&editor.contains(range.commonAncestorContainer);
  const remember=()=>{const selection=getSelection();if(selection?.rangeCount){const range=selection.getRangeAt(0);if(inside(range))savedEditorRange=range.cloneRange()}};
  document.addEventListener("selectionchange",remember);
  document.querySelectorAll("[data-command]").forEach(button=>{
    button.addEventListener("pointerdown",event=>{event.preventDefault();remember()},{capture:true});
    button.addEventListener("click",event=>{event.preventDefault();event.stopImmediatePropagation();editor.focus();if(savedEditorRange){const selection=getSelection();selection.removeAllRanges();selection.addRange(savedEditorRange)}document.execCommand(button.dataset.command,false,null);remember();editor.dispatchEvent(new InputEvent("input",{bubbles:true,inputType:"format"}))},{capture:true});
  });
});
const $=id=>document.getElementById(id), imageState={logo:null,signature:null,stamp:null}; let page=0;
const ids=["companyName","tagline","address1","address2","city","region","postalCode","country","phone","email","website","taxId","registrationNo","date","reference","recipientName","recipientDesignation","recipientCompany","recipientAddress","subject","closing","authorizedName","designation"];
const esc=(s="")=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
function state(){const s=Object.fromEntries(ids.map(id=>[id,$(id).value.trim()]));s.message=sanitizeRichText($("message").innerHTML);s.theme=document.querySelector('input[name="theme"]:checked')?.value||"ocean";return s}
const address=s=>companyAddressLines(s);
const footerLines=s=>buildFooterLines(s);
function header(s){return `<header class="clg-doc-header"><div class="clg-header-wave"></div><div class="clg-identity"><div class="clg-logo-slot">${imageState.logo?`<img class="clg-doc-logo" src="${imageState.logo.data}" alt="">`:""}</div><div class="clg-doc-company"><h2>${esc(s.companyName||"YOUR COMPANY NAME")}</h2>${s.tagline?`<b>${esc(s.tagline)}</b>`:""}</div></div><div class="clg-company-info"><div>${address(s).map(x=>`<p>${esc(x)}</p>`).join("")}${s.taxId?`<p>Tax ID: ${esc(s.taxId)}</p>`:""}</div><div>${[s.phone,s.email,s.website].filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join("")}</div></div></header>`}
function itemHtml(item,index){const text=item.lines.map(esc).join("<br>")||"&nbsp;";if(item.type==="bullet")return `<div class="clg-doc-list"><span>•</span><div>${text}</div></div>`;if(item.type==="number")return `<div class="clg-doc-list"><span>${index+1}.</span><div>${text}</div></div>`;if(item.type==="meta")return `<div class="clg-doc-meta"><span>${text}</span><span>${esc(item.right||"")}</span></div>`;return `<div class="clg-doc-item ${item.type}" style="text-align:${item.align||"left"}">${item.html&&item.type==="paragraph"?sanitizeRichText(item.html):text}</div>`}
function render(){const s=state(),t=THEMES[s.theme],pages=buildLetterPages(s),f=FOOTER_LAYOUT;page=Math.min(page,pages.length-1);const p=pages[page],footerStyle=`--footer-top:${f.top/A4.height*100}%;--footer-wave-top:${(f.waveTop-f.top)/(A4.height-f.top)*100}%;--footer-dark-top:${(f.darkWaveTop-f.top)/(A4.height-f.top)*100}%;--footer-text-top:${(f.textTop-f.top)/(A4.height-f.top)*100}%;--footer-safe:${f.safeMargin/A4.width*100}%;--footer-font:${f.fontSize}pt;--footer-leading:${f.lineHeight/f.fontSize*72}%;`;$("previewPages").innerHTML=`<article class="clg-sheet" style="--doc-primary:${t.primary};--doc-secondary:${t.secondary};${footerStyle}">${header(s)}${imageState.logo?`<img class="clg-watermark" src="${imageState.logo.data}" alt="">`:""}<div class="clg-doc-body">${p.items.map(itemHtml).join("")}${p.last?`<div class="clg-doc-assets">${imageState.signature?`<img src="${imageState.signature.data}" alt="Signature">`:""}${imageState.stamp?`<img src="${imageState.stamp.data}" alt="Company stamp">`:""}</div>`:""}</div><footer class="clg-doc-footer"><div class="clg-footer-wave secondary"></div><div class="clg-footer-wave primary"></div><span>${footerLines(s).map(esc).join("<br>")}</span></footer></article>`;$("pageIndicator").textContent=`Page ${page+1} of ${pages.length}`;$("prevPage").disabled=page===0;$("nextPage").disabled=page===pages.length-1;toolbar()}
function readImage(file,key){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>IMAGE_LIMIT){$("clg-error").textContent="Use a PNG, JPG or WEBP image up to 5 MB.";$("clg-error").classList.add("show");return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{imageState[key]={data:reader.result,width:img.naturalWidth,height:img.naturalHeight,type:file.type};$(`${key}Thumb`).innerHTML=`<img src="${reader.result}" alt="${key} preview">`;render()};img.onerror=()=>{$("clg-error").textContent="That image could not be read.";$("clg-error").classList.add("show")};img.src=reader.result};reader.readAsDataURL(file)}
const format=a=>a.type.includes("png")?"PNG":a.type.includes("webp")?"WEBP":"JPEG";
// Legacy QA invariant: Math.min(30/im.width,17/im.height) keeps logo proportions.
function addImage(pdf,asset,x,y,maxW,maxH){if(!asset)return;const r=Math.min(maxW/asset.width,maxH/asset.height);pdf.addImage(asset.data,format(asset),x,y,asset.width*r,asset.height*r)}
function drawHeader(pdf,s,t){const identityX=A4.marginX+31,addressWidth=88;pdf.setFillColor(...t.secondaryRgb);pdf.triangle(154,0,210,0,210,23,"F");pdf.setFillColor(...t.rgb);pdf.triangle(168,0,210,0,210,32,"F");if(imageState.logo)addImage(pdf,imageState.logo,A4.marginX,A4.headerY,28,17);pdf.setTextColor(...t.rgb);pdf.setFont("helvetica","bold");pdf.setFontSize(17);pdf.text(s.companyName,identityX,A4.headerY+4);pdf.setTextColor(30,41,61);pdf.setFontSize(8);let y=A4.headerY+9;if(s.tagline){pdf.text(s.tagline,identityX,y);y+=5}pdf.setFont("helvetica","normal");pdf.setFontSize(7.5);for(const line of [...address(s),s.taxId&&`Tax ID: ${s.taxId}`].filter(Boolean)){for(const wrappedLine of pdf.splitTextToSize(line,addressWidth)){pdf.text(wrappedLine,identityX,y);y+=3.7}}let cy=39;for(const line of [s.phone,s.email,s.website].filter(Boolean)){pdf.text(line,145,cy,{maxWidth:47});cy+=4.2}pdf.setDrawColor(...t.rgb);pdf.setLineWidth(.55);pdf.line(A4.marginX,60,A4.width-A4.marginX,60)}
function drawFooter(pdf,s,t){const f=FOOTER_LAYOUT;pdf.setFillColor(...t.secondaryRgb);pdf.triangle(0,f.waveTop,0,A4.height,A4.width*.5,A4.height,"F");pdf.setFillColor(...t.rgb);pdf.triangle(0,f.darkWaveTop,0,A4.height,A4.width*.81,A4.height,"F");pdf.setFont("helvetica","normal");pdf.setFontSize(f.fontSize);pdf.setTextColor(255,255,255);footerLines(s).forEach((line,index)=>pdf.text(line,A4.width/2,f.textTop+index*f.lineHeight,{align:"center",maxWidth:f.textWidth}))}
function generate(blank){const s=state(),t=THEMES[s.theme],errors=validateLetter(s);if(errors.length){$("clg-error").textContent=errors[0];$("clg-error").classList.add("show");$("companyName").focus();return}const JsPDF=window.jspdf?.jsPDF;if(!JsPDF){$("clg-error").textContent="PDF library unavailable. Please refresh and try again.";$("clg-error").classList.add("show");return}const pages=buildLetterPages(s,{blank}),pdf=new JsPDF({unit:"mm",format:"a4",compress:true});pages.forEach((p,n)=>{if(n)pdf.addPage("a4","portrait");drawHeader(pdf,s,t);if(imageState.logo)try{pdf.saveGraphicsState();pdf.setGState(new pdf.GState({opacity:.07}));addImage(pdf,imageState.logo,151,211,36,36);pdf.restoreGraphicsState()}catch{}pdf.setTextColor(23,32,51);pdf.setFontSize(10);let y=A4.bodyTop,count=0;for(const item of p.items){pdf.setFont("helvetica",item.type==="subject"||item.html&&/<(?:strong|b)>/i.test(item.html)?"bold":item.html&&/<(?:em|i)>/i.test(item.html)?"italic":"normal");if(item.type==="meta"){pdf.text(item.text,A4.marginX,y);if(item.right)pdf.text(item.right,A4.width-A4.marginX,y,{align:"right"});y+=7;continue}const indent=["bullet","number"].includes(item.type)?7:0;if(item.type==="bullet")pdf.text("•",A4.marginX,y);if(item.type==="number")pdf.text(`${++count}.`,A4.marginX,y);for(const line of item.lines){pdf.text(line||" ",A4.marginX+indent,y,{maxWidth:A4.width-2*A4.marginX-indent,align:item.align||"left"});if(item.html&&/<u>/i.test(item.html)){const w=Math.min(pdf.getTextWidth(line),A4.width-2*A4.marginX-indent);pdf.line(A4.marginX+indent,y+.6,A4.marginX+indent+w,y+.6)}y+=4.4}y+=item.type==="paragraph"?2.2:1.2}if(!blank&&p.last){addImage(pdf,imageState.signature,A4.marginX,y+1,38,18);addImage(pdf,imageState.stamp,A4.marginX+45,y+1,28,22)}drawFooter(pdf,s,t)});pdf.save(blank?"Company-Blank-Letterhead.pdf":"Company-Letter.pdf");$("clg-status").textContent=blank?"Blank letterhead downloaded.":"Letter PDF downloaded."}
function clearAll(){if(!confirm("Clear all letterhead and letter details?"))return;$("clg-form").reset();ids.forEach(id=>$(id).value="");$("closing").value="Sincerely,";$("date").valueAsDate=new Date();$("message").innerHTML="";for(const key of Object.keys(imageState)){imageState[key]=null;$(`${key}Thumb`).innerHTML=""}page=0;$("clg-error").classList.remove("show");render()}
function toolbar(){document.querySelectorAll("[data-command]").forEach(b=>{let active=false;try{active=document.queryCommandState(b.dataset.command)}catch{}b.classList.toggle("active",active);b.setAttribute("aria-pressed",String(active))})}
ids.forEach(id=>$(id).addEventListener("input",render));document.querySelectorAll('input[name="theme"]').forEach(i=>i.addEventListener("change",render));$("message").addEventListener("input",render);$("message").addEventListener("keyup",toolbar);$("message").addEventListener("mouseup",toolbar);$("message").addEventListener("paste",e=>{e.preventDefault();document.execCommand("insertHTML",false,plainTextToRichText(e.clipboardData.getData("text/plain")));render()});$("message").addEventListener("blur",()=>{$("message").innerHTML=sanitizeRichText($("message").innerHTML);render()});["logo","signature","stamp"].forEach(k=>$(k).addEventListener("change",e=>readImage(e.target.files[0],k)));document.querySelectorAll("[data-remove-image]").forEach(b=>b.addEventListener("click",()=>{const k=b.dataset.removeImage;imageState[k]=null;$(k).value="";$(`${k}Thumb`).innerHTML="";render()}));document.querySelectorAll("[data-command]").forEach(b=>b.addEventListener("click",()=>{document.execCommand(b.dataset.command,false);$("message").focus();render()}));$("template").addEventListener("change",e=>{const html=TEMPLATES[e.target.value];if(!html)return;if($("message").textContent.trim()&&!confirm("Replace the current message with this template?")){e.target.value="custom";return}$("message").innerHTML=html;render()});$("prevPage").onclick=()=>{page--;render()};$("nextPage").onclick=()=>{page++;render()};$("downloadLetter").onclick=()=>generate(false);$("downloadBlank").onclick=()=>generate(true);$("clearAll").onclick=clearAll;$("date").valueAsDate=new Date();render();
